CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS drivers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(100) UNIQUE NULL, secret_hash VARCHAR(255) NULL, active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS readings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vehicle_id INT UNSIGNED NOT NULL, driver_id INT UNSIGNED NOT NULL, reading_type ENUM('start','end') NOT NULL, odometer INT UNSIGNED NOT NULL, recorded_at DATETIME NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (vehicle_id) REFERENCES vehicles(id), FOREIGN KEY (driver_id) REFERENCES drivers(id), INDEX (vehicle_id,recorded_at));
